function reportSales(){return repo.state.sales.filter(s=>dayKey(s.at)>=ui.reportFrom&&dayKey(s.at)<=ui.reportTo);}
function reports(){
  const sales=reportSales(),s=stats(sales),top=productTotals(sales),payments=['Cash','UPI','Card'].map(p=>({name:p,value:stats(sales.filter(s=>s.payment===p)).revenue}));
  const cats=CATEGORIES.map(c=>({name:c,value:top.filter(p=>p.category===c).reduce((a,p)=>a+p.revenue,0)})).filter(c=>c.value>0),total=cats.reduce((a,c)=>a+c.value,0);let cumulative=0;
  const colors=['#315c3c','#7f9c63','#abc086','#dbc38a','#d4ddd0'];
  const gradient=cats.map((c,i)=>{const start=cumulative;cumulative+=c.value/(total||1)*100;return `${colors[i]} ${start}% ${cumulative}%`;}).join(',');
  return `${pageHead('A LITTLE INSIGHT GOES A LONG WAY','Know what makes your shop grow.','Clear numbers. Better decisions. Fresher possibilities.',button('Export report','export-report','download','secondary'))}<div class="report-period"><div>${icon('calendar')}<strong>Your reporting period</strong></div><div class="date-filters"><label>From<input id="report-from" type="date" value="${ui.reportFrom}"></label><span>—</span><label>To<input id="report-to" type="date" value="${ui.reportTo}"></label><button class="text-btn" data-action="report-week">Last 7 days</button></div></div>${ui.reportFrom>ui.reportTo?'<p class="inline-warning">Choose an end date on or after the start date.</p>':''}<div class="metrics-grid">${metric('Net sales',currency(s.revenue),'wallet','<span>After discounts · excludes voids</span>',true)}${metric('Cost of goods sold',currency(s.revenue-s.profit),'box','<span>Cost recorded at time of sale</span>')}${metric('Gross profit',currency(s.profit),'trend',`<span>${s.revenue?(s.profit/s.revenue*100).toFixed(1):'0'}% gross margin · before expenses</span>`)}${metric('Average order',currency(s.average),'bag',`<span>Across ${s.orders} completed orders</span>`)}</div><div class="report-grid"><section class="panel"><div class="panel-heading"><div><h2>What’s growing?</h2><p>Sales value by category, before discounts</p></div></div>${cats.length?`<div class="category-chart"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Category sales: ${cats.map(c=>h(c.name)+' '+currency(c.value)).join(', ')}"><div><small>Total sales value</small><strong>${currency(total)}</strong></div></div><div class="donut-legend">${cats.map((c,i)=>`<div><i style="background:${colors[i]}"></i><span>${c.name}</span><strong>${(c.value/total*100).toFixed(1)}%</strong></div>`).join('')}</div></div>`:empty('Insights are on their way','Complete a sale to start seeing trends.')}</section><section class="panel"><div class="panel-heading"><div><h2>How customers pay</h2><p>Completed sales, after discounts</p></div></div><div class="payment-report">${payments.map(p=>`<div><span class="payment-report-icon">${icon(p.name==='Cash'?'cash':p.name==='UPI'?'qr':'card')}</span><div><div><strong>${p.name}</strong><span>${currency(p.value)}</span></div><div class="mini-bar"><i style="width:${s.revenue?p.value/s.revenue*100:0}%"></i></div><small>${sales.filter(s=>s.status==='completed'&&s.payment===p.name).length} transactions</small></div></div>`).join('')}</div></section></div><section class="panel"><div class="panel-heading"><div><h2>Product performance</h2><p>Quantities and gross item margin for this period</p></div></div>${top.length?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th class="numeric">Quantity sold</th><th class="numeric">Sales value</th><th class="numeric">Item cost</th><th class="numeric">Item margin</th></tr></thead><tbody>${top.map(p=>{const cost=sales.filter(s=>s.status==='completed').flatMap(s=>s.lines).filter(l=>l.productId===p.productId).reduce((a,l)=>a+l.costTotal,0);return `<tr><td><div class="product-cell"><span class="produce-avatar cat-${CATEGORIES.indexOf(p.category)}">${productArtwork(p)}</span><strong>${h(p.name)}</strong></div></td><td>${p.category}</td><td class="numeric">${qty(roundQty(p.sold))} ${p.unit}</td><td class="numeric amount">${currency(p.revenue)}</td><td class="numeric">${currency(cost)}</td><td class="numeric green-text">${currency(p.revenue-cost)}</td></tr>`;}).join('')}</tbody></table></div><div class="table-footer">Item margins exclude order-level discounts. Gross profit above includes all discounts.</div>`:empty('Nothing to report just yet','Try another date range or complete your first sale.')}</section>`;
}
function settings(){
  const s=repo.state.settings,u=user();
  return `${pageHead('MAKE YOURSELF AT HOME','Your shop. Your way.','The little details that make this workspace yours.')}<div class="settings-grid"><section class="panel settings-panel"><div class="panel-heading"><div><h2>Shop details</h2><p>These details appear on your receipts</p></div>${icon('leaf')}</div><form id="settings-form" class="padded-form"><label>Shop name<input name="shopName" value="${h(s.shopName)}" maxlength="80" required></label><div class="form-row"><label>Phone number<input name="phone" type="tel" value="${h(s.phone)}" maxlength="40"></label><label>Currency<select name="currency">${[['INR','₹ · Indian rupee'],['USD','$ · US dollar'],['GBP','£ · British pound'],['EUR','€ · Euro']].map(([v,l])=>`<option value="${v}" ${s.currency===v?'selected':''}>${l}</option>`).join('')}</select></label></div><small class="field-hint">Changing currency changes the symbol only; it does not convert existing amounts.</small><label>Shop address<textarea name="address" rows="2" maxlength="250" placeholder="Add your shop address">${h(s.address)}</textarea></label><label>Receipt message<input name="receiptFooter" value="${h(s.receiptFooter)}" maxlength="250"></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">${icon('check')} Save shop details</button></form></section><div class="settings-column"><section class="panel settings-panel"><div class="panel-heading"><div><h2>Keep a little backup</h2><p>Your records deserve a safe place</p></div>${icon('download')}</div><div class="settings-section"><div class="local-info">${icon('info')}<p>${repo.cloud?'Shop records are saved in your private Google Drive database and shared with connected devices. Download a backup regularly. Erasing data here clears it for everyone.':'Data is saved in this browser only. Clearing site data or changing browsers removes access to it. Export a backup regularly; CSV exports cannot restore the workspace.'}</p></div><div class="backup-stats"><span><strong>${repo.state.products.length}</strong> products</span><span><strong>${repo.state.sales.length}</strong> receipts</span><span><strong>${repo.state.movements.length}</strong> movements</span></div><div class="button-row">${button('Download backup','backup','download')}${button('Restore backup','restore','upload','secondary')}</div><input id="restore-file" type="file" accept=".json,application/json" hidden></div></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>Your account</h2><p>${h(u.email)} · Administrator</p></div>${icon('user')}</div><form id="account-form" class="padded-form"><label>Display name<input name="name" value="${h(u.name)}" required maxlength="80"></label><label>Current password<input name="current" type="password" autocomplete="current-password" required></label><label>New password <span class="optional">optional</span><input name="password" type="password" autocomplete="new-password" minlength="6" placeholder="Leave blank to keep your password"></label><p class="form-error" role="alert"></p><button type="submit" class="btn secondary">Update account</button></form></section></div><section class="panel settings-panel full-width"><div class="settings-danger"><div><h2>Erase shop data</h2><p>Delete products, photos, purchases, sales, stock records and entered shop details. Login accounts and passwords stay exactly the same.</p></div>${button('Erase shop data','reset','trash','danger-outline')}</div></section></div>`;
}

function openModal(title,body,cls=''){
  modalCloseFocus=document.activeElement;
  $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;
  document.body.classList.add('modal-open');
  $('#app').inert=true;
  const target=$('.modal [autofocus]')||$('.modal input:not([type=hidden])')||$('.modal');target?.focus();
}
function closeModal(){if(busy)return;imageRevision++;imageBusy=false;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');$('#app').inert=false;if(modalCloseFocus?.isConnected)modalCloseFocus.focus();}
const formFooter=label=>`<p class="form-error" role="alert"></p><div class="modal-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${label}</button></div>`;
function productModal(id){
  const p=repo.state.products.find(p=>p.id===id);
  productImageDraft=p?.image||'';imageRevision++;imageBusy=false;
  const nextSku=`VEG-${String(repo.state.products.length+1).padStart(3,'0')}`;
  openModal(p?'Edit product':'Something fresh for your shelves',`<form id="product-form" class="modal-form"><input type="hidden" name="id" value="${p?.id||''}"><p class="modal-intro">${p?'Update product details and pricing. Use stock adjustments to record quantity changes.':'Add a product, set its prices and record your opening stock.'}</p><div class="photo-editor"><div id="product-photo-preview">${productArtwork(p||{name:'Product photo',emoji:'🥬'})}</div><div><label>Product photo<input id="product-photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="field-hint">JPG, PNG or WebP · up to 10 MB. Resized and saved on this device.</p><button type="button" class="text-btn" data-action="remove-photo">Remove photo</button><p id="photo-status" role="status"></p></div></div><div class="form-row product-name-row"><label>Product icon<select name="emoji" class="emoji-select">${EMOJIS.map(e=>`<option ${e===(p?.emoji||'🥬')?'selected':''}>${e}</option>`).join('')}</select></label><label>Product name<input name="name" value="${h(p?.name||'')}" placeholder="e.g. Fresh tomatoes" required minlength="2" maxlength="80" autofocus></label></div><div class="form-row"><label>SKU<input name="sku" value="${h(p?.sku||nextSku)}" required minlength="2" maxlength="30"></label><label>Category<select name="category">${CATEGORIES.map(c=>`<option ${c===(p?.category||'Vegetables')?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="form-row three"><label>Sold by<select name="unit">${UNITS.map(u=>`<option value="${u}" ${u===(p?.unit||'kg')?'selected':''}>${{kg:'Kilogram (kg)',pcs:'Piece (pcs)',bunch:'Bunch'}[u]}</option>`).join('')}</select></label><label>Cost / unit (${repo.state.settings.currency})<input name="cost" type="number" min="0" step="0.01" value="${p?p.cost/100:''}" required></label><label>Price / unit (${repo.state.settings.currency})<input name="price" type="number" min="0.01" step="0.01" value="${p?p.price/100:''}" required></label></div><div class="form-row">${p?'':`<label>Opening stock<input name="stock" type="number" min="0" step="0.001" value="0" required></label><label>Purchased goods value (${repo.state.settings.currency})<input name="purchaseValue" type="number" min="0" step="0.01" placeholder="Auto: stock × unit cost"></label>`}<label>Low stock alert at<input name="minStock" type="number" min="0" step="0.001" value="${p?.minStock??10}" required></label></div><p class="field-hint">${p?'Existing purchase records stay unchanged when you edit unit cost. Use Record purchase for additional goods value.':'Opening stock automatically sets a recovery target. Enter the total goods value to calculate its cost per unit.'}</p><label>Supplier <span class="optional">optional</span><input name="supplier" value="${h(p?.supplier||'')}" placeholder="Farm or supplier name" maxlength="100"></label>${formFooter(p?'Save product':'Add product')}</form>`);
}
function stockModal(id){const p=repo.state.products.find(p=>p.id===id);openModal('Every little bit, accounted for.',`<form id="stock-form" class="modal-form"><input name="productId" type="hidden" value="${p.id}"><div class="stock-modal-product"><span class="produce-avatar cat-${CATEGORIES.indexOf(p.category)}">${productArtwork(p)}</span><div><strong>${h(p.name)}</strong><span>${qty(p.stock)} ${p.unit} currently in stock</span></div>${status(p)}</div><label>Movement type<select name="type" id="movement-type"><option value="receive">Receive stock · add a delivery</option><option value="waste">Record wastage · remove stock</option><option value="adjust">Stock count · set actual quantity</option></select></label><div class="form-row"><label><span id="stock-quantity-label">Quantity to receive (${p.unit})</span><input name="quantity" type="number" step="${p.unit==='kg'?'0.001':'1'}" min="${p.unit==='kg'?'0.001':'1'}" required autofocus></label><label id="purchase-cost-label">Purchase cost / ${p.unit} (${repo.state.settings.currency})<input name="purchaseCost" type="number" min="0" step="0.01" value="${p.cost/100}"></label></div><label id="purchase-value-label">Total purchased goods value (${repo.state.settings.currency})<input name="purchaseValue" type="number" min="0" step="0.01" placeholder="Auto: quantity × purchase cost"></label><p id="stock-hint" class="field-hint">The delivery value is added to your recovery target. Receiving stock updates the product’s weighted average cost. Sales keep the cost recorded at checkout.</p><label>Reason / delivery reference<textarea name="note" placeholder="e.g. Morning delivery from Green Valley Farms" required minlength="3" maxlength="250" rows="2"></textarea></label>${formFooter('Record stock movement')}</form>`);}
function confirmModal(title,message,formId,id,actionLabel,extra=''){openModal(title,`<form id="${formId}" class="modal-form"><input type="hidden" name="id" value="${h(id)}"><p class="modal-intro">${message}</p>${extra}${formFooter(actionLabel)}</form>`);}
function checkoutModal(){
  const calc=calculateCart(repo.state,ui.cart,ui.discount);
  openModal('One more fresh sale.',`<form id="checkout-form" class="modal-form"><input name="token" type="hidden" value="${uid()}"><input name="expectedTotal" type="hidden" value="${calc.total}"><div class="checkout-summary"><span>Total to pay</span><strong>${currency(calc.total)}</strong><p>${ui.cart.length} ${ui.cart.length===1?'product':'products'} · ${ui.payment} · ${h(ui.customer||'Walk-in customer')}</p></div>${ui.payment==='Cash'?`<label>Cash received (${repo.state.settings.currency})<input name="received" id="cash-received" type="number" min="${calc.total/100}" step="0.01" value="${calc.total/100}" required autofocus></label><div class="change-line"><span>Change to return</span><strong id="cash-change">${currency(0)}</strong></div>`:`<div class="local-info">${icon(ui.payment==='UPI'?'qr':'card')}<p>Collect ${currency(calc.total)} using your ${ui.payment==='UPI'?'UPI app':'card terminal'} before completing this sale. This app records the payment; it does not process it.</p></div><label class="checkbox-label"><input name="paid" type="checkbox" required> I have received the payment</label>`}<p class="field-hint">Completing the sale will save the receipt and deduct stock.</p>${formFooter('Complete sale')}</form>`,'checkout-modal');
}
function receiptModal(id){
  const s=repo.state.sales.find(s=>s.id===id),shop=repo.state.settings;
  if(!s)throw new Error('Receipt not found.');
  openModal('Your sale, neatly wrapped.',`<div class="receipt-paper" id="receipt-print"><div class="receipt-brand">${icon('leaf')}<h2>${h(shop.shopName)}</h2>${shop.address?`<p>${h(shop.address)}</p>`:''}${shop.phone?`<p>${h(shop.phone)}</p>`:''}<span>SALES RECEIPT</span></div><div class="receipt-meta"><div><strong>${h(s.number)}</strong><span>${date(s.at)} · ${time(s.at)}</span></div><div><span>${h(s.customer)}</span><span>Served by ${h(s.actor)}</span></div></div>${s.status==='voided'?`<div class="void-banner">VOIDED · ${h(s.voidReason)}<small>Stock restored. Any money refund must be handled separately.</small></div>`:''}<table class="receipt-lines"><thead><tr><th>Item</th><th class="numeric">Amount</th></tr></thead><tbody>${s.lines.map(l=>`<tr><td><strong>${h(l.name)}</strong><small>${qty(l.quantity)} ${l.unit} × ${currency(l.price)}</small></td><td class="numeric">${currency(l.total)}</td></tr>`).join('')}</tbody></table><div class="receipt-totals"><div><span>Subtotal</span><span>${currency(s.subtotal)}</span></div>${s.discount?`<div><span>Discount</span><span>−${currency(s.discount)}</span></div>`:''}<div class="receipt-total"><strong>Total</strong><strong>${currency(s.total)}</strong></div><div><span>Payment method</span><span>${s.payment}</span></div>${s.payment==='Cash'?`<div><span>Cash received</span><span>${currency(s.received)}</span></div><div><span>Change</span><span>${currency(s.change)}</span></div>`:''}</div><div class="receipt-thanks">${h(shop.receiptFooter)}<small>Locally recorded receipt · No tax calculated</small></div></div><div class="receipt-actions">${user().role==='admin'&&s.status==='completed'?`<button class="btn text-danger" data-action="void-sale" data-id="${s.id}">${icon('undo')} Void sale</button>`:'<span></span>'}<div>${button('Done','close-modal','check','secondary')}${button('Print receipt','print-receipt','print')}</div></div>`,'receipt-modal');
}
function navigate(page){
  if(user()?.role==='sales'&&!['pos','stock','sales'].includes(page))throw new Error('Management access is required.');
  ui.page=page;ui.basketOpen=false;ui.search='';ui.category='All products';ui.stockFilter='all';ui.inventoryTab='products';ui.menu=false;render();window.scrollTo(0,0);
}
function changeMode(mode){ui.mode=mode;navigate(mode==='sales'?'pos':'overview');}
function addToCart(id,increment){
  const p=repo.state.products.find(p=>p.id===id&&p.active);if(!p)throw new Error('This product is unavailable.');
  const line=ui.cart.find(l=>l.productId===id);const baseStep=p.unit==='kg'?0.5:1;const step=increment??(line?baseStep:Math.min(baseStep,p.stock));const next=roundQty((line?.quantity||0)+step);
  if(next>p.stock)throw new Error(`Only ${qty(p.stock)} ${p.unit} is available.`);
  if(next<=0){ui.cart=ui.cart.filter(l=>l.productId!==id);}else if(line)line.quantity=next;else ui.cart.push({productId:id,quantity:next});
  renderKeepingFocus();
}
function syncPurchaseAmounts(form,quantityName,costName,source){
  const total=form.elements.purchaseValue;if(!total)return;
  const quantity=Number(form.elements[quantityName].value),cost=form.elements[costName];
  if(source==='purchaseValue') total.dataset.manual=total.value===''?'':'true';
  if(source===costName) total.dataset.manual='';
  if(total.dataset.manual==='true') {
    if(quantity>0&&total.value!=='')cost.value=(Number(total.value)/quantity).toFixed(2);
  }else if(quantity>0&&cost.value!=='')total.value=(Math.round(Number(cost.value)*100*quantity)/100).toFixed(2);
  else total.value='';
}
async function handlePhoto(file,form){
  if(!file)return;
  const revision=++imageRevision;imageBusy=true;
  const save=$('[type=submit]',form),status=$('#photo-status');save.disabled=true;status.textContent='Preparing your photo…';status.className='field-hint';
  try {
    const prepared=await prepareProductImage(file);
    if(revision!==imageRevision||!form.isConnected)return;
    productImageDraft=prepared;
    $('#product-photo-preview').innerHTML=productArtwork({name:form.elements.name.value||'Product photo',image:prepared});
    status.textContent=`Photo ready · ${Math.ceil(prepared.length*3/4/1024)} KB · saved when you save the product`;
  }catch(e){if(revision===imageRevision&&form.isConnected){status.textContent=e.message;status.className='form-error';}}
  finally{if(revision===imageRevision){imageBusy=false;if(form.isConnected)save.disabled=false;}}
}
function download(content,filename,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function csv(rows,filename){const escape=value=>{let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('\uFEFF'+rows.map(row=>row.map(escape).join(',')).join('\r\n'),filename,'text/csv;charset=utf-8');toast('Export downloaded.');}
function exportSales(){const sales=repo.state.sales.filter(s=>(!ui.salesFrom||dayKey(s.at)>=ui.salesFrom)&&(!ui.salesTo||dayKey(s.at)<=ui.salesTo)&&(ui.saleStatus==='all'||s.status===ui.saleStatus)&&(!ui.search||(s.number+' '+s.customer+' '+s.actor).toLowerCase().includes(ui.search.toLowerCase())));csv([['Receipt','Date','Customer','Cashier','Payment','Status','Subtotal','Discount','Total','Cost of goods','Gross profit','Currency'],...sales.map(s=>[s.number,s.at,s.customer,s.actor,s.payment,s.status,s.subtotal/100,s.discount/100,s.total/100,s.cost/100,s.status==='completed'?(s.total-s.cost)/100:0,repo.state.settings.currency])],`freshleaf-sales-${today()}.csv`);}
function helpModal(){openModal('A little guide to your workspace',`<div class="modal-form guide"><div>${icon('grid')}<div><h3>Management keeps the big picture clear.</h3><p>Add or archive products, set prices, record deliveries and wastage, check reports and back up your records.</p></div></div><div>${icon('cart')}<div><h3>Sales keeps the counter moving.</h3><p>Add items to the basket, enter a quantity (up to 3 decimals for kg), choose a payment method and complete the sale. Stock is deducted automatically.</p></div></div><div>${icon('refresh')}<div><h3>Two panels. One set of records.</h3><p>${repo.cloud?'The laptop and phone share a private Drive database. Stock is checked again when saving. Keep the internet connected; the screen refreshes every 30 seconds.':'Both panels share data in this browser and website. Tabs update automatically. Data does not sync to another browser or device.'}</p></div></div><div>${icon('download')}<div><h3>Keep your work safe.</h3><p>${repo.cloud?'Management can download a JSON backup in Settings. Keep the Drive database private. Cash, UPI and card payments are recorded manually.':'Download a JSON backup in Settings. Local role logins organise the workspace; anyone with browser access can modify local data. Cash, UPI and card payments are recorded manually.'}</p></div></div><button class="btn primary" data-action="close-modal">Got it, let’s grow ${icon('sprout')}</button></div>`);}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled||busy)return;event.preventDefault();
  const action=el.dataset.action,id=el.dataset.id;
  try {
    switch(action){
      case 'toggle-password':{const input=$('[name=password]',$('#login-form'));input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?'Show':'Hide';break;}
      case 'demo-admin':case 'demo-sales':{const role=action==='demo-admin'?'admin':'sales';const form=$('#login-form');form.elements.email.value=`${role}@freshleaf.local`;form.elements.password.value=role==='admin'?'admin123':'sales123';form.requestSubmit();break;}
      case 'nav':navigate(el.dataset.page);break;
      case 'home':navigate(ui.mode==='management'?'overview':'pos');break;
      case 'switch-mode':changeMode(ui.mode==='management'?'sales':'management');break;
      case 'open-pos':changeMode('sales');break;
      case 'logout':repo.logout();ui.cart=[];ui.discount=0;ui.customer='';closeModal();render();break;
      case 'menu':ui.menu=true;$('.workspace').classList.add('menu-open');syncMenu();break;
      case 'close-menu':ui.menu=false;$('.workspace').classList.remove('menu-open');syncMenu();break;
      case 'help':helpModal();break;
      case 'install-info':installModal();break;
      case 'install-app':if(!await installApp())installModal();break;
      case 'show-basket':ui.basketOpen=true;renderMain();window.scrollTo(0,0);$('.basket-back')?.focus();break;
      case 'hide-basket':ui.basketOpen=false;renderMain();window.scrollTo(0,0);$('#pos-search')?.focus({preventScroll:true});break;
      case 'purchase':purchaseModal(id);break;
      case 'calculator':calculatorModal(id);break;
      case 'weight-preset':$('#calculator-unit').value='g';$('#calculator-weight').min='1';$('#calculator-weight').step='1';$('#calculator-weight').value=el.dataset.grams;updateWeightCalculator();break;
      case 'remove-photo':imageRevision++;imageBusy=false;productImageDraft='';$('#product-photo-file').value='';$('#product-photo-preview').innerHTML=productArtwork({name:'Product photo',emoji:$('#product-form').elements.emoji.value});$('#photo-status').textContent='Photo will be removed when you save the product.';$('#photo-status').className='field-hint';$('#product-form [type=submit]').disabled=false;break;
      case 'close-modal':closeModal();break;
      case 'add-product':requireAdmin(user());productModal();break;
      case 'edit-product':requireAdmin(user());productModal(id);break;
      case 'restock':requireAdmin(user());stockModal(id);break;
      case 'archive-product':{requireAdmin(user());const p=repo.state.products.find(p=>p.id===id);confirmModal(p.active?'Take this product off the shelf?':'Bring this product back?',p.active?`${h(p.name)} will be hidden from new sales. Its ${qty(p.stock)} ${p.unit} of stock and all historical records will be kept. You can restore it from Archived products.`:`${h(p.name)} will be available in inventory and the sales panel again.`,'archive-form',id,p.active?'Archive product':'Restore product');break;}
      case 'inventory-tab':ui.inventoryTab=el.dataset.tab;ui.search='';renderMain();break;
      case 'low-stock':case 'alerts':navigate(user().role==='admin'?'inventory':'stock');ui.stockFilter='low';renderMain();break;
      case 'pos-category':ui.category=el.dataset.category;renderKeepingFocus();break;
      case 'add-cart':addToCart(id);break;
      case 'cart-plus':addToCart(id);break;
      case 'cart-minus':{const p=repo.state.products.find(p=>p.id===id);addToCart(id,p.unit==='kg'?-0.5:-1);break;}
      case 'remove-cart':ui.cart=ui.cart.filter(l=>l.productId!==id);renderMain();break;
      case 'clear-cart':confirmModal('Start a fresh basket?','Remove all items and the discount from this current order? No sale has been recorded.','clear-cart-form','','Clear basket');break;
      case 'payment':ui.payment=el.dataset.payment;renderMain();break;
      case 'checkout':checkoutModal();break;
      case 'receipt':receiptModal(id);break;
      case 'print-receipt':window.print();break;
      case 'void-sale':requireAdmin(user());confirmModal('Void this sale and return the stock?','All items will be returned to inventory and this sale will be excluded from revenue. Only use this when the goods are back in stock or the original sale was a mistake. Any payment refund must be handled separately.','void-form',id,'Void sale & restore stock','<label>Reason<textarea name="reason" minlength="3" maxlength="250" required rows="2" placeholder="Why is this sale being voided?"></textarea></label>');break;
      case 'report-week':ui.reportFrom=offsetDay(-6);ui.reportTo=today();renderMain();break;
      case 'export-stock':csv([['SKU','Product','Category','Unit','Cost','Selling price','Stock','Reorder level','Stock value at cost','Supplier','Active','Currency'],...repo.state.products.map(p=>[p.sku,p.name,p.category,p.unit,p.cost/100,p.price/100,p.stock,p.minStock,Math.round(p.stock*p.cost)/100,p.supplier,p.active,repo.state.settings.currency])],`freshleaf-stock-${today()}.csv`);break;
      case 'export-ledger':csv([['Date','Product','Unit','Movement','Change','Balance','Note','Reference','Recorded by'],...repo.state.movements.map(m=>[m.at,m.productName,m.unit,m.type,m.delta,m.balance,m.note,m.reference,m.actor])],`freshleaf-ledger-${today()}.csv`);break;
      case 'export-sales':exportSales();break;
      case 'export-purchases':{requireAdmin(user());const progress=recoveryStats(repo.state);csv([['Date','Product','Source','Quantity','Unit','Goods value','Recovered from sales','Still to recover','Note','Recorded by','Currency'],...repo.state.purchases.map(p=>[p.at,p.productName,p.source,p.quantity??'',p.unit,p.amount/100,progress.byPurchase[p.id].recovered/100,progress.byPurchase[p.id].remaining/100,p.note,p.actor,repo.state.settings.currency])],`freshleaf-purchases-${today()}.csv`);break;}
      case 'export-report':{const sales=reportSales(),s=stats(sales);csv([['Report period',ui.reportFrom,ui.reportTo],['Currency',repo.state.settings.currency],['Net sales',s.revenue/100],['Cost of goods sold',(s.revenue-s.profit)/100],['Gross profit',s.profit/100],['Completed orders',s.orders],[],['Product','Category','Unit','Quantity sold','Sales value before discounts'],...productTotals(sales).map(p=>[p.name,p.category,p.unit,roundQty(p.sold),p.revenue/100])],`freshleaf-report-${ui.reportFrom}-to-${ui.reportTo}.csv`);break;}
      case 'backup':requireAdmin(user());download(JSON.stringify(await repo.backup(),null,2),`freshleaf-backup-${today()}.json`,'application/json');toast('Backup downloaded. Keep it somewhere safe.');break;
      case 'restore':requireAdmin(user());$('#restore-file').click();break;
      case 'reset':requireAdmin(user());confirmModal('Erase all shop data?','This permanently deletes products, photos, purchases, recovery records, sales, stock movements and entered shop details. Login emails, passwords and roles are preserved. Download a backup first.','reset-form','','Erase shop data','<label>Type CLEAR to confirm<input name="confirmation" pattern="CLEAR" placeholder="CLEAR" autocomplete="off" required></label>');break;
    }
  }catch(e){toast(e.message,'error');}
});

document.addEventListener('input',event=>{
  const el=event.target;
  if(['calculator-rate','calculator-weight'].includes(el.id))updateWeightCalculator();
  if(el.form?.getAttribute('id')==='product-form'&&['stock','cost','purchaseValue'].includes(el.name))syncPurchaseAmounts(el.form,'stock','cost',el.name);
  if(el.form?.getAttribute('id')==='stock-form'&&['quantity','purchaseCost','purchaseValue'].includes(el.name)&&el.form.elements.type.value==='receive')syncPurchaseAmounts(el.form,'quantity','purchaseCost',el.name);
  if(['inventory-search','pos-search','sales-search','purchase-search'].includes(el.id)){ui.search=el.value;renderKeepingFocus();}
  if(el.id==='cart-discount'){ui.discount=el.value;updateTotals();}
  if(el.id==='customer-name')ui.customer=el.value;
  if(el.dataset.quantity){const line=ui.cart.find(l=>l.productId===el.dataset.quantity);if(line){line.quantity=el.value===''?'':Number(el.value);const p=repo.state.products.find(p=>p.id===line.productId);el.closest('.basket-item').querySelector('.basket-item-bottom>strong').textContent=currency(Math.round((Number(line.quantity)||0)*p.price));const badge=document.querySelector(`.pos-product[data-id="${p.id}"] .in-cart`);if(badge)badge.textContent=`${qty(Number(line.quantity)||0)} in basket`;updateTotals();}}
  if(el.id==='cash-received'){const total=Number($('#checkout-form').elements.expectedTotal.value);$('#cash-change').textContent=currency(Math.max(0,Math.round(Number(el.value)*100)-total));}
});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.id==='product-photo-file'){await handlePhoto(el.files[0],$('#product-form'));return;}
  if(el.id==='calculator-product')syncCalculatorProduct();
  if(el.id==='calculator-unit'){
    const weight=$('#calculator-weight'),value=Number(weight.value);
    weight.value=el.value==='kg'?roundQty(value/1000):Math.round(value*1000);
    weight.min=el.value==='g'?'1':'0.001';weight.step=el.value==='g'?'1':'0.001';updateWeightCalculator();
  }
  if(['purchase-product','purchase-kind'].includes(el.id))syncPurchaseForm();
  const mapping={'range-select':['range',Number], 'category-filter':['category',String], 'stock-filter':['stockFilter',String], 'sales-from':['salesFrom',String], 'sales-to':['salesTo',String], 'sale-status':['saleStatus',String], 'report-from':['reportFrom',String], 'report-to':['reportTo',String]};
  if(mapping[el.id]){ui[mapping[el.id][0]]=mapping[el.id][1](el.value);renderMain();}
  if(el.id==='movement-type'){
    const form=$('#stock-form'),p=repo.state.products.find(p=>p.id===form.elements.productId.value);
    $('#stock-quantity-label').textContent=`${el.value==='adjust'?'Actual stock count':el.value==='waste'?'Quantity to remove':'Quantity to receive'} (${p.unit})`;
    form.elements.quantity.min=el.value==='adjust'?'0':p.unit==='kg'?'0.001':'1';
    $('#purchase-cost-label').hidden=el.value!=='receive';form.elements.purchaseCost.disabled=el.value!=='receive';
    $('#purchase-value-label').hidden=el.value!=='receive';form.elements.purchaseValue.disabled=el.value!=='receive';
    if(el.value==='receive')syncPurchaseAmounts(form,'quantity','purchaseCost','quantity');
    $('#stock-hint').textContent=el.value==='receive'?'Receiving stock updates the product’s weighted average cost. Sales keep the cost recorded at checkout.':el.value==='adjust'?'Enter the actual quantity on your shelf. The difference is recorded in the stock ledger.':'Record damaged, spoiled or unusable produce. This reduces inventory without creating a sale.';
  }
  if(el.id==='restore-file'){
    try{const file=el.files[0];if(!file)return;if(file.size>15*1024*1024)throw new Error('The backup file must be smaller than 15 MB.');pendingRestore=validateState(JSON.parse(await file.text()));confirmModal('Restore this shop backup?',`Replace this browser’s current records with ${pendingRestore.products.length} products, ${pendingRestore.sales.length} receipts and ${pendingRestore.movements.length} stock movements from <strong>${h(pendingRestore.settings.shopName)}</strong>. Accounts and passwords from the backup will replace the current accounts. You will need to sign in again.`,'restore-form','','Restore backup','<label>Type RESTORE to confirm<input name="confirmation" pattern="RESTORE" placeholder="RESTORE" autocomplete="off" required></label>');}
    catch(e){toast(e instanceof SyntaxError?'This file is not valid JSON.':e.message,'error');}
    finally{el.value='';}
  }
});

document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;if(busy||!form.checkValidity())return;
  const values=Object.fromEntries(new FormData(form));const error=$('.form-error',form);if(error)error.textContent='';
  const submit=$('[type=submit]',form);const original=submit?.innerHTML;busy=true;if(submit){submit.disabled=true;submit.textContent='Saving…';}
  try{
    let message='',receiptId=null;
    switch(form.getAttribute('id')){
      case 'login-form':{const u=await repo.login(values.email,values.password);setInitialWorkspace(u);ui.search='';render();window.scrollTo(0,0);return;}
      case 'product-form':if(imageBusy)throw new Error('Please wait for the photo to finish processing.');values.image=productImageDraft;await repo.perform('product',values);message=values.id?'Product updated.':'New product added.';break;
      case 'stock-form':await repo.perform('stock',values);message='Stock movement recorded.';break;
      case 'purchase-form':await repo.perform('purchase',values);message='Purchase recorded. Both panels have the updated recovery target.';break;
      case 'calculator-form':{const p=repo.state.products.find(p=>p.id===$('#calculator-product').value&&p.active&&p.unit==='kg');if(!p)throw new Error('Select an available product first.');const result=calculatorValue();if(result.price!==p.price)throw new Error('The product price changed. Select it again to update the calculation.');addToCart(p.id,result.quantity);ui.mode='sales';ui.page='pos';ui.search='';ui.category='All products';message=`${qty(result.quantity)} kg of ${p.name} added to the basket.`;break;}
      case 'archive-form':await repo.perform('archive',{id:values.id});message='Product availability updated.';break;
      case 'checkout-form':receiptId=await repo.perform('checkout',{items:ui.cart,discount:ui.discount,payment:ui.payment,customer:ui.customer,received:values.received,token:values.token,expectedTotal:Number(values.expectedTotal)});ui.cart=[];ui.discount=0;ui.customer='';ui.basketOpen=false;message='Sale completed. Inventory updated.';break;
      case 'clear-cart-form':ui.cart=[];ui.discount=0;ui.customer='';break;
      case 'void-form':await repo.perform('void',{id:values.id,reason:values.reason});message='Sale voided and stock restored.';receiptId=values.id;break;
      case 'settings-form':await repo.perform('settings',values);message='Shop details saved.';break;
      case 'account-form':await repo.updateAccount(values);message='Account updated.';break;
      case 'reset-form':if(values.confirmation!=='CLEAR')throw new Error('Type CLEAR to confirm.');await repo.perform('erase',{confirmation:values.confirmation});ui.cart=[];ui.discount=0;ui.customer='';ui.basketOpen=false;message='Shop data erased. Logins and passwords are unchanged. Your empty shop is ready. Add your first product in Inventory.';break;
      case 'restore-form':if(values.confirmation!=='RESTORE'||!pendingRestore)throw new Error('Type RESTORE to confirm.');await repo.perform('restore',{confirmation:values.confirmation,state:pendingRestore});repo.logout();ui.cart=[];ui.discount=0;pendingRestore=null;message='Backup restored. Sign in with an account from the backup.';break;
      default:return;
    }
    busy=false;closeModal();render();if(message)toast(message);if(receiptId)receiptModal(receiptId);
  }catch(e){if(error)error.textContent=e.message;else toast(e.message,'error');}
  finally{busy=false;if(submit?.isConnected){submit.disabled=false;submit.innerHTML=original;}}
});

document.addEventListener('keydown',event=>{
  const modal=$('.modal');
  if(event.key==='Escape'){if(modal)closeModal();else if(ui.menu){ui.menu=false;$('.workspace')?.classList.remove('menu-open');syncMenu();}}
  if(modal&&event.key==='Tab'){
    const focusable=[...modal.querySelectorAll('button:not(:disabled),input:not([type=hidden]):not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(el=>el.getClientRects().length);
    const first=focusable[0],last=focusable.at(-1);
    if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}
    else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
  }
  if(event.key==='/'&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const search=$('#pos-search')||$('#inventory-search')||$('#sales-search');if(search){event.preventDefault();search.focus();}}
});
window.addEventListener('storage',event=>{
  if(repo.cloud||event.key!==STORAGE_KEY)return;
  try{repo.state=validateState(repo.read());ui.cart=ui.cart.filter(line=>repo.state.products.some(p=>p.id===line.productId&&p.active));if(!ui.cart.length){ui.discount=0;ui.customer='';}if(!user())closeModal();render();toast('Shop data updated from another tab.');}catch(e){toast(e.message,'error');}
});

try{await repo.init();if(user())setInitialWorkspace(user());render();}
catch(e){$('#app').innerHTML=`<main class="startup-error"><span class="brand-symbol">${icon('leaf')}</span><h1>Your workspace needs a moment.</h1><p>${h(e.message)}</p><p>Use a current browser with site storage enabled, on localhost or an HTTPS address.</p><button class="btn primary" onclick="location.reload()">Try again</button><button id="recovery-export" class="btn secondary">Save stored data for recovery</button></main>`;$('#recovery-export').addEventListener('click',()=>{const raw=repo.cloud?localStorage.getItem(repo.cacheKey):localStorage.getItem(STORAGE_KEY);if(raw)download(raw,`freshleaf-recovery-${today()}.json`,'application/json');else toast('No stored shop data was found.','error');});}

function setInitialWorkspace(u){const sales=u.role==='sales'||matchMedia('(max-width:650px)').matches||isStandalone()||new URLSearchParams(location.search).get('workspace')==='sales';ui.mode=sales?'sales':'management';ui.page=sales?'pos':'overview';ui.basketOpen=false;}
function mobileNavigation(){return `<nav class="mobile-sales-nav" aria-label="Mobile sales navigation">${[['pos','cart','Sell'],['stock','box','Stock'],['sales','receipt','History']].map(([page,ic,label])=>`<button data-action="nav" data-page="${page}" ${ui.page===page?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}<button data-action="menu">${icon('menu')}<span>Menu</span></button></nav>`;}
function mobileRecovery(s){return `<details class="mobile-recovery"><summary><span class="recovery-mini-icon">${icon('wallet')}</span><span>First, recover your investment<strong>${currency(s.remaining)} <small>left to recover</small></strong></span>${icon('down')}</summary><div class="recovery-mini-progress" aria-label="${s.percent.toFixed(1)}% investment recovered"><i style="width:${s.percent}%"></i></div><div class="mobile-recovery-details"><p>Goods purchased <strong>${currency(s.invested)}</strong></p><p>Recovered from sales <strong>${currency(s.recovered)}</strong></p><p>Sales beyond recovered purchases <strong>${currency(s.surplus)}</strong></p><small>Never resets. Sales recover the oldest unpaid goods first. New deliveries add their cost; remaining stock stays available to sell.</small></div></details>`;}
function installModal(){const info=appStatus();openModal('Your counter, one tap away',`<div class="modal-form install-guide"><img src="assets/icon-192.png" width="64" height="64" alt="Freshleaf app icon"><p class="modal-intro">Add Freshleaf to your phone’s home screen. Its icon opens the sales panel in an app window. Both admin and sales accounts can use it.</p>${info.installed?'<div class="local-info">This window is already running as an app.</div>':info.canInstall?button('Install sales app','install-app','download'):''}<ol><li><strong>Android · Chrome</strong><p>Open your published shop address. In the browser menu, choose Install app or Add to Home screen.</p></li><li><strong>iPhone · Safari</strong><p>Open your shop address, tap Share → Add to Home Screen. Enable Open as Web App if shown, then tap Add.</p></li></ol><p class="field-hint" id="shared-connection-status">${repo.cloud?h(repo.status):'Local mode · devices are not connected yet'}</p><p class="field-hint">${repo.cloud?'The app screen can open offline. Reconnect to save shared stock, purchases or sales.':'Configure Google Apps Script before using the laptop and phone together.'}</p><p class="field-hint" id="app-offline-status">${h(info.status)}</p><p class="field-hint">${info.updateReady?'An update is ready. Close all Freshleaf tabs and app windows, then reopen to apply it.':'Use the same shop address on every device.'}</p><button class="btn primary" data-action="close-modal">Got it</button></div>`);}
window.addEventListener('freshleaf-app-status',()=>{const status=$('#app-offline-status');if(status)status.textContent=appStatus().status;});
registerApp();

let sharedRenderPending=false;
function paintConnectionStatus(){const node=$('.local-status');if(node&&repo.cloud){node.textContent=repo.status;node.title=repo.status;}const info=$('#shared-connection-status');if(info)info.textContent=repo.status;}
async function syncSharedShop(){
  if(!repo.cloud||!user()||busy||document.hidden)return;
  try{const oldEpoch=repo.epoch;const changed=await repo.refresh();if(changed){
    ui.cart=ui.cart.filter(line=>repo.state.products.some(p=>p.id===line.productId&&p.active));
    if(oldEpoch!==repo.epoch){ui.cart=[];ui.discount=0;ui.customer='';closeModal();toast('Shop data was reset on another device.');}
    sharedRenderPending=true;
  }if(sharedRenderPending&&!$('.modal')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){render();sharedRenderPending=false;}}catch{if(!user()){closeModal();render();}}
  paintConnectionStatus();
}
window.addEventListener('freshleaf-cloud-status',paintConnectionStatus);
window.addEventListener('online',syncSharedShop);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncSharedShop();});
if(repo.cloud)setInterval(syncSharedShop,30000);
